
from pathlib import Path
import base64

FILES = {'apps/dashboard/product_contexts.py': '', 'apps/dashboard/workbench.py': '', 'apps/dashboard/views.py': '', 'apps/dashboard/urls.py': '', 'templates/base.html': '', 'templates/dashboard/organization.html': '', 'templates/dashboard/document_detail.html': '', 'templates/dashboard/control_detail.html': '', 'templates/dashboard/user_profile.html': '', 'templates/dashboard/report_center.html': '', 'static/css/product_v64.css.append': ''}

for name, encoded in FILES.items():
    path = Path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.suffix == ".append":
        real = Path(str(path)[:-7])
        if real.exists():
            text = real.read_text(encoding="utf-8")
            marker = "/* V65 */"
            block = base64.b64decode(encoded).decode("utf-8")
            if marker not in text:
                real.write_text(text + "\n\n" + block, encoding="utf-8")
            print("OK:", real)
        continue

    if path.exists():
        backup = path.with_name(path.name + ".before_v65.bak")
        if not backup.exists():
            backup.write_text(path.read_text(encoding="utf-8"), encoding="utf-8")

    path.write_bytes(base64.b64decode(encoded))
    print("OK:", path)

# fix generic document list title buttons if user clicks docs/controls/users from related urls
selector = Path("apps/dashboard/selectors.py")
if selector.exists():
    stext = selector.read_text(encoding="utf-8")
    backup = selector.with_name(selector.name + ".before_v65.bak")
    if not backup.exists():
        backup.write_text(stext, encoding="utf-8")
    # V65.1: get_clause_context normaliza el código dentro de la función
    selector.write_text(stext, encoding="utf-8")

print("")
print("V65 Focus 1 instalada.")
print("Incluye:")
print("- Organización sin bloque 'Sin área' cuando no exista área cargada.")
print("- Crear usuario desde un cargo/puesto.")
print("- Ficha especializada de documento con vista previa.")
print("- Ficha especializada de control con documentos vinculados.")
print("- Perfil de usuario mejorado.")
print("- Centro de reportes y métricas.")
